    pdf: value => vega_statistics_module_densityNormal(value, mu, sigma),
    cdf: value => vega_statistics_module_cumulativeNormal(value, mu, sigma),
    icdf: p => vega_statistics_module_quantileNormal(p, mu, sigma)
