  // 4-character punctuator: >>>=

  ch4 = parser_source.substr(parser_index, 4);

  if (ch4 === '>>>=') {
    parser_index += 4;
    return {
      type: parser_TokenPunctuator,
      value: ch4,
      start: start,
      end: parser_index
    };
  }

  // 3-character punctuators: === !== >>> <<= >>=

  ch3 = ch4.substr(0, 3);

  if (ch3 === '>>>' || ch3 === '<<=' || ch3 === '>>=') {
    parser_index += 3;
    return {
      type: parser_TokenPunctuator,
      value: ch3,
      start: start,
      end: parser_index
    };
  }

