  if (parser_isIdentifierStart(parser_source.charCodeAt(parser_index)) || parser_isDecimalDigit(parser_source.charCodeAt(parser_index))) {
    parser_throwError({}, parser_MessageUnexpectedToken, parser_ILLEGAL);
  }

